import sys
from collections import deque

def bfs(start, board, cost, n, m, k):
    queue = deque([start])
    visited = [[False] * m for _ in range(n)]
    visited[start[0]][start[1]] = True
    selected = set()
    if board[start[0]][start[1]] > 0:
        selected.add(board[start[0]][start[1]])
    total_cost = cost[start[0]][start[1]]

    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and board[nx][ny] != -1:
                visited[nx][ny] = True
                if board[nx][ny] > 0:
                    selected.add(board[nx][ny])
                total_cost += cost[nx][ny]
                queue.append((nx, ny))
                if len(selected) >= k:
                    return total_cost
    return float('inf')

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    k = int(input[index + 2])
    index += 3

    board = []
    for i in range(n):
        row = list(map(int, input[index:index + m]))
        board.append(row)
        index += m

    cost = []
    for i in range(n):
        row = list(map(int,input[index:index + m]))
        cost.append(row)
        index += m

    min_cost = float('inf')
    for i in range(n):
        for j in range(m):
            if board[i][j] != -1:
                current_cost = bfs((i, j), board, cost, n, m, k)
                min_cost = min(min_cost, current_cost)

    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

main()
